import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';

/**
 * Telefon profil ızgarası (onaylı maket 4): kullanıcının mesajlarındaki fotoğraflar 3 sütunlu,
 * boşluksuz kare ızgarada. Veri, profil sayfasının zaten yüklediği mesaj listesinden (PostListState) gelir;
 * "Daha fazla" listeyi bir sonraki sayfayla genişletir.
 */
export default class MobileProfileGrid extends Component {
  view() {
    const state = this.attrs.state;
    const posts = (state.getAllItems ? state.getAllItems() : []).filter(p => p && p.contentType && p.contentType() === 'comment');
    const tiles = [];
    posts.forEach(post => {
      const box = document.createElement('div');
      box.innerHTML = post.contentHtml() || '';
      const imgs = [...box.querySelectorAll('img')].filter(i => !i.classList.contains('emoji') && (i.getAttribute('src') || '').length);
      // Kare küçük görsel için 480 px yeterli (görsel sunucusu ?w= ile boyutlandırır)
      if (imgs.length) tiles.push({
        post,
        src: imgs[0].getAttribute('src').replace(/([?&])w=\d+/, '$1w=480'),
        alt: imgs[0].getAttribute('alt') || '',
        multi: imgs.length > 1
      });
    });
    const loading = state.isLoading && state.isLoading();
    const more = state.hasNext && state.hasNext();
    return m("div", {
      className: "MobileProfileGrid"
    }, tiles.length ? m("div", {
      className: "MobileProfileGrid-tiles"
    }, tiles.map(t => m("a", {
      href: app.route.post(t.post),
      className: "MobileProfileGrid-tile",
      onclick: e => {
        e.preventDefault();
        m.route.set(app.route.post(t.post));
      }
    }, m("img", {
      src: t.src,
      alt: t.alt,
      loading: "lazy",
      decoding: "async"
    }), t.multi ? m("i", {
      className: "icon fas fa-clone"
    }) : null))) : !loading ? m("p", {
      className: "MobileProfileGrid-empty"
    }, "Hen\xFCz foto\u011Fraf payla\u015F\u0131lmam\u0131\u015F.") : null, loading ? m("div", {
      className: "MobileProfileGrid-loading"
    }, "Y\xFCkleniyor\u2026") : null, !loading && more ? m("button", {
      type: "button",
      className: "MobileProfileGrid-more",
      onclick: () => state.loadNext()
    }, "Daha fazla g\xF6ster") : null);
  }
}
flarum.reg.add('framio-custom-homepage', 'forum/components/MobileProfileGrid', MobileProfileGrid);